<template><section><div class="page-heading"><div><h1>企业品牌</h1><p>品牌内容会直接显示在企业登录页首屏。</p></div><el-button type="primary" :loading="saving" @click="save">保存品牌</el-button></div><div class="brand-grid"><el-form :model="brand" label-position="top"><el-form-item label="品牌标题"><el-input v-model="brand.title" maxlength="40" show-word-limit/></el-form-item><el-form-item label="品牌标语"><el-input v-model="brand.slogan" maxlength="60" show-word-limit/></el-form-item><el-form-item label="品牌正文"><el-input v-model="brand.body" type="textarea" :rows="4" maxlength="120" show-word-limit/></el-form-item><el-divider>登录背景资源</el-divider><el-form-item label="资源地址"><el-input v-model="brand.background_url" placeholder="https://.../background.webp 或 asset://..."/></el-form-item><el-form-item label="选择本地文件以生成元数据"><input class="file-input" type="file" accept="image/jpeg,image/png,image/webp" @change="inspectFile"></el-form-item><div class="metadata"><el-form-item label="Content-Type"><el-input v-model="brand.background_content_type" placeholder="image/webp"/></el-form-item><el-form-item label="字节数"><el-input-number v-model="brand.background_size_bytes" :min="0" :max="5242880" controls-position="right"/></el-form-item></div><el-form-item label="SHA256"><el-input v-model="brand.background_sha256" maxlength="64"/></el-form-item><el-alert v-if="validationError" :title="validationError" type="error" :closable="false"/></el-form><div class="preview" :style="previewStyle"><div class="preview-shade"></div><div class="preview-copy"><Icon name="shield" size="xl"/><small>企业安全门户</small><h2>{{ brand.title||'企业工作台' }}</h2><strong>{{ brand.slogan }}</strong><p>{{ brand.body }}</p></div></div></div></section></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import Icon from'@/components/icons/Icon.vue';import{enterpriseAPI}from'@/api/enterprise';import{validateBrand,validateImageFile}from'@/features/enterprise/validation';import type{EnterpriseBrand}from'@/types/enterprise';const saving=ref(false),validationError=ref(''),brand=reactive<EnterpriseBrand>({title:'',body:'',slogan:'',background_url:'',background_content_type:'',background_sha256:'',background_size_bytes:0});const previewStyle=computed(()=>brand.background_url?{backgroundImage:`url(${brand.background_url})`}:{});async function load(){Object.assign(brand,await enterpriseAPI.getAdminBrand())}async function inspectFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const error=validateImageFile(file);if(error){validationError.value=error;return}brand.background_content_type=file.type;brand.background_size_bytes=file.size;const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());brand.background_sha256=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');validationError.value=validateBrand(brand)}async function save(){validationError.value=validateBrand(brand);if(validationError.value)return;saving.value=true;try{Object.assign(brand,await enterpriseAPI.updateBrand({...brand}));ElMessage.success('企业品牌已保存')}finally{saving.value=false}}onMounted(()=>load().catch(()=>{validationError.value='品牌信息加载失败'}));</script>
<style scoped>.page-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:22px}.page-heading h1{margin:0 0 6px;font-size:26px}.page-heading p{margin:0;color:#64748b}.brand-grid{display:grid;grid-template-columns:minmax(0,520px) minmax(320px,1fr);gap:36px;align-items:start}.metadata{display:grid;grid-template-columns:1fr 1fr;gap:16px}.file-input{width:100%;padding:10px;border:1px solid #dcdfe6;border-radius:4px;background:white}.preview{position:sticky;top:92px;min-height:520px;border-radius:8px;background:#173f3d center/cover;color:white;overflow:hidden}.preview-shade{position:absolute;inset:0;background:rgba(9,31,31,.72)}.preview-copy{position:absolute;left:0;right:0;bottom:0;padding:42px}.preview-copy small{display:block;margin:20px 0 8px;color:#a7f3d0}.preview-copy h2{margin:0 0 16px;font-size:38px;overflow-wrap:anywhere}.preview-copy p{color:#d1fae5;line-height:1.6}@media(max-width:900px){.brand-grid{grid-template-columns:1fr}.preview{position:relative;top:0;min-height:380px}}@media(max-width:640px){.page-heading{flex-direction:column}.page-heading .el-button{width:100%}.metadata{grid-template-columns:1fr}}</style>
